8	/**
9	 * First step of {@code POST /api/owners}, ahead of any validation or persistence. When the request
10	 * carries an {@code Idempotency-Key} that has already produced an owner it raises
11	 * {@link IdempotentReplayException}, short-circuiting the pipeline so the original owner is returned
12	 * with 200 rather than the create running again (which would otherwise be rejected as a 409
13	 * duplicate). Otherwise it publishes the key for {@link RecordIdempotencyKey} to store once the
14	 * owner has been created.
15	 *
16	 * <p>The header is optional: a request without one (or with a blank one) simply proceeds as an
17	 * ordinary create and is never recorded.
18	 */
19	public class CheckIdempotencyKey {
20	
21	    public void service(@RequestHeader(name = "Idempotency-Key", required = false) String idempotencyKey,
22	            IdempotencyStore store, Out<String> keyOut) throws IdempotentReplayException {
23	        String key = (idempotencyKey == null || idempotencyKey.isBlank()) ? "" : idempotencyKey;
24	        if (!key.isEmpty()) {
25	            Integer existingId = store.find(key);
26	            if (existingId != null) {
27	                throw new IdempotentReplayException(existingId);
28	            }
29	        }
30	        // Publish for RecordIdempotencyKey; empty means "no key", which it skips.
31	        keyOut.set(key);
32	    }
33	}
