35	package org.springframework.samples.petclinic.rest.function.owner;
36	
37	import java.util.ArrayList;
38	import java.util.List;
39	
40	import jakarta.validation.ConstraintViolation;
41	import jakarta.validation.Validator;
42	import net.officefloor.plugin.variable.Out;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
45	import org.springframework.samples.petclinic.rest.function.common.Postcodes;
46	import org.springframework.web.bind.annotation.RequestBody;
47	
48	/**
49	 * First step of {@code POST /api/owners}. Rejects a body that is missing (absent) or blank
50	 * (whitespace only) in any of firstName, lastName, address, city or telephone — {@code @Size(min = 1)}
51	 * on the DTO does not catch a whitespace-only value, so the check is explicit here. The remaining
52	 * schema constraints (pattern, max length) are validated too, so a bad value is still a 400.
53	 *
54	 * <p>Binds the body directly (no {@code @Valid}) so that a missing field surfaces as this rule's
55	 * {@code errors} response rather than the generic schema-validation escalation, and publishes the
56	 * body for {@link BuildOwner} to consume.
57	 */
58	public class ValidateOwnerFields {
59	
60	    public void service(@RequestBody OwnerFieldsDto request, Validator validator, Out<OwnerFieldsDto> validated)
61	            throws MissingOwnerFieldsException {
62	        List<String> errors = new ArrayList<>();
63	        normalizeAddress(request);
64	        addIfBlank(errors, "firstName", request.getFirstName());
65	        addIfBlank(errors, "lastName", request.getLastName());
66	        addIfBlank(errors, "address", request.getAddress());
67	        addIfBlank(errors, "city", request.getCity());
68	        normalizeTelephone(errors, request);
69	        for (ConstraintViolation<OwnerFieldsDto> violation : validator.validate(request)) {
70	            String field = violation.getPropertyPath().toString();
71	            if (!field.isEmpty() && !errors.contains(field)) {
72	                errors.add(field);
73	            }
74	        }
75	        validatePostcode(errors, request);
76	        if (!errors.isEmpty()) {
77	            throw new MissingOwnerFieldsException(errors);
78	        }
79	        normalizeEmail(request);
80	        validated.set(request);
81	    }
82	
83	    /**
84	     * Email is optional. When absent nothing is done; when present the schema {@code @Email}
85	     * constraint (checked above) has already rejected a syntactically invalid address with a
86	     * {@code 400}, so a value reaching here is valid and is stored and returned lower-cased.
87	     */
88	    private static void normalizeEmail(OwnerFieldsDto request) {
89	        String email = request.getEmail();
90	        if (email != null) {
91	            request.setEmail(email.toLowerCase(java.util.Locale.ROOT));
92	        }
93	    }
94	
95	    /**
96	     * Canonically normalize the address (trim, collapse whitespace, upper-case, expand common
97	     * abbreviations) and write it back onto the request so it is stored and returned in normalized
98	     * form. The structured form is preferred: when {@code addressLine1} normalizes to a non-blank
99	     * value the structured lines are normalized and the flat {@code address} is set to the composed
100	     * value — the normalized {@code addressLine1} with a single space and the normalized
101	     * {@code addressLine2} appended when {@code addressLine2} is present. Otherwise the flat
102	     * {@code address} input is normalized and the structured lines are cleared, keeping earlier
103	     * flat-only owners backward compatible. Running before the blank check means an owner that
104	     * supplies neither form — and so has a blank composed {@code address} — is rejected as an
105	     * {@code address} required-field error (400).
106	     */
107	    private static void normalizeAddress(OwnerFieldsDto request) {
108	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
109	        if (!line1.isEmpty()) {
110	            String line2 = AddressNormalizer.normalize(request.getAddressLine2());
111	            request.setAddressLine1(line1);
112	            if (line2.isEmpty()) {
113	                request.setAddressLine2(null);
114	                request.setAddress(line1);
115	            }
116	            else {
117	                request.setAddressLine2(line2);
118	                request.setAddress(line1 + " " + line2);
119	            }
120	        }
121	        else {
122	            request.setAddressLine1(null);
123	            request.setAddressLine2(null);
124	            request.setAddress(AddressNormalizer.normalize(request.getAddress()));
125	        }
126	    }
127	
128	    /**
129	     * Postcode is optional and validated only when present. Its 4-digit format is enforced by the
130	     * schema {@code @Pattern} (checked above, so a malformed value is already a {@code postcode}
131	     * error). When it is well-formed it must also be in range for the region derived from the
132	     * owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region
133	     * accepts any 4-digit postcode. An out-of-range postcode is a {@code postcode} error (400).
134	     */
135	    private static void validatePostcode(List<String> errors, OwnerFieldsDto request) {
136	        String postcode = request.getPostcode();
137	        if (postcode != null && !errors.contains("postcode")
138	                && !Postcodes.isValidForCity(postcode, request.getCity())) {
139	            errors.add("postcode");
140	        }
141	    }
142	
143	    private static void addIfBlank(List<String> errors, String name, String value) {
144	        if (value == null || value.isBlank()) {
145	            errors.add(name);
146	        }
147	    }
148	
149	    /**
150	     * Normalize the telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
151	     * '+' with country code is kept as-is; otherwise the number is assumed to be Australian ('+61')
152	     * and a single leading '0' is dropped from the national digits. The result must have 8 to 15
153	     * digits after the '+'. The E.164 value is written back onto the request so it is stored and
154	     * returned as {@code telephone}. Anything that cannot form a valid E.164 number is a
155	     * {@code telephone} error (400).
156	     */
157	    private static void normalizeTelephone(List<String> errors, OwnerFieldsDto request) {
158	        String e164 = toE164(request.getTelephone());
159	        if (e164 == null) {
160	            errors.add("telephone");
161	            return;
162	        }
163	        request.setTelephone(e164);
164	    }
165	
166	    /**
167	     * Country codes with a fixed national-number length. When a number's country code appears here
168	     * its national digits (everything after the code) must match exactly, otherwise it is rejected;
169	     * country codes not listed fall back to the generic 8–15 total-digit rule. '+61' (Australia)
170	     * requires 9 national digits, '+1' (NANP) requires 10.
171	     */
172	    private static final java.util.Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY =
173	            java.util.Map.of("61", 9, "1", 10);
174	
175	    /**
176	     * Convert a raw telephone into E.164 form, or return {@code null} when it cannot form a valid
177	     * E.164 number (fewer than 8 or more than 15 digits after the '+', a national-number length that
178	     * is wrong for its country code, or stray non-digit characters remaining after the allowed
179	     * separators are stripped).
180	     */
181	    static String toE164(String value) {
182	        if (value == null) {
183	            return null;
184	        }
185	        String cleaned = value.replaceAll("[\\s()-]", "");
186	        String digits;
187	        if (cleaned.startsWith("+")) {
188	            digits = cleaned.substring(1);
189	        }
190	        else {
191	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
192	            digits = "61" + national;
193	        }
194	        if (!digits.matches("[0-9]{8,15}")) {
195	            return null;
196	        }
197	        if (!hasValidNationalLength(digits)) {
198	            return null;
199	        }
200	        return "+" + digits;
201	    }
202	
203	    /**
204	     * For a country code with a fixed national-number length, check the national digits (everything
205	     * after the code) match that length exactly. Unknown country codes pass (already bounded by the
206	     * generic 8–15 total-digit rule).
207	     */
208	    private static boolean hasValidNationalLength(String digits) {
209	        for (java.util.Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY.entrySet()) {
210	            String code = entry.getKey();
211	            if (digits.startsWith(code)) {
212	                return digits.length() - code.length() == entry.getValue();
213	            }
214	        }
215	        return true;
216	    }
217	}
