316	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
317	import org.springframework.samples.petclinic.rest.function.common.IdentityKeys;
318	
319	/**
320	 * The duplicate-detection step of {@code POST /api/owners}. Runs after {@link ValidateOwnerFields}
321	 * has normalized the telephone and email. It computes the request's deterministic
322	 * {@code householdId} from its last name and postcode (see {@link Households#householdId}) and
323	 * rejects the create with a 409 Conflict in two cases:
324	 *
325	 * <ul>
326	 * <li><b>Identity duplicate</b> — the request's whole {@code identityKey}
327	 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) equals an existing
328	 * owner's. This always rejects, even when {@code sharesHousehold} is set.</li>
329	 * <li><b>Household duplicate</b> — an existing owner already occupies the same household (same
330	 * computed {@code householdId}, i.e. same last name and postcode). This rejects <em>unless</em> the
331	 * request opts in with {@code sharesHousehold: true}, in which case the owner is created as a
332	 * declared household member.</li>
333	 * </ul>
334	 *
335	 * <p>{@code sharesHousehold} therefore only bypasses the household-duplicate block; it never lets a
336	 * full identity duplicate through.
337	 */
338	public class RejectDuplicateIdentity {
339	
340	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
341	            throws DuplicateIdentityException {
342	        String householdId = Households.householdId(request.getLastName(), request.getPostcode());
343	        String identityKey = IdentityKeys.of(request.getTelephone(), request.getEmail(), householdId);
344	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
345	        for (Owner existing : ownerRepository.findAll()) {
346	            if (existing.isDeleted()) {
347	                // A soft-deleted owner is no longer a live identity; it cannot block a create.
348	                continue;
349	            }
350	            if (identityKey.equals(IdentityKeys.of(existing))) {
351	                throw new DuplicateIdentityException(identityKey);
352	            }
353	            if (!sharesHousehold && householdId.equals(householdIdOf(existing))) {
354	                throw new DuplicateIdentityException(householdId);
355	            }
356	        }
357	    }
358	
359	    /** The household an existing owner belongs to, computed from its last name and postcode. */
360	    private static String householdIdOf(Owner existing) {
361	        return Households.householdId(existing.getLastName(), existing.getPostcode());
362	    }
363	}
