650	package org.springframework.samples.petclinic.rest.function.owner;
651	
652	import net.officefloor.plugin.variable.Val;
653	import org.springframework.samples.petclinic.model.Owner;
654	import org.springframework.samples.petclinic.repository.OwnerRepository;
655	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
656	
657	/**
658	 * Soft-match step of {@code POST /api/owners}. By the time it runs the request has already passed
659	 * {@link RejectDuplicateIdentity}, so it is <em>not</em> a hard duplicate; this step then looks for a
660	 * weaker signal that it might be one anyway: an existing owner that shares this owner's
661	 * {@code lastName} (compared case-insensitively) and {@code postcode} but has a <em>different</em>
662	 * telephone. Such an owner is still created, but is flagged with {@code possibleDuplicate = true} and
663	 * {@code possibleDuplicateOf} set to the matching owner's id (the lowest id when several match).
664	 * When nothing matches, {@code possibleDuplicate} is set to {@code false} and no id is recorded.
665	 *
666	 * <p>A <em>declared</em> household member — one created with {@code sharesHousehold: true} — is never
667	 * flagged: it already reached this step by opting past the household-duplicate block in
668	 * {@link RejectDuplicateIdentity}, so sharing a same-household owner's lastName and postcode is
669	 * expected, not a suspected duplicate.
670	 *
671	 * <p>Runs after {@link BuildOwner} so the owner carries its normalized lastName, postcode and
672	 * telephone, and before {@link SaveOwner} so the comparison sees only owners that existed before this
673	 * create — the new owner is not yet persisted and so never matches itself. {@code @Val} yields the
674	 * built owner, mutated in place and persisted by the save step.
675	 */
676	public class AssignPossibleDuplicate {
677	
678	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
679	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
680	            // A declared household member is not a suspected duplicate.
681	            owner.setPossibleDuplicate(false);
682	            owner.setPossibleDuplicateOf(null);
683	            return;
684	        }
685	        String lastName = Households.normalizeName(owner.getLastName());
686	        String postcode = normalizePostcode(owner.getPostcode());
687	        String telephone = owner.getTelephone();
688	        Integer match = null;
689	        if (postcode != null) {
690	            for (Owner existing : ownerRepository.findAll()) {
691	                if (existing.isDeleted()) {
692	                    // A soft-deleted owner is not a live duplicate to flag against.
693	                    continue;
694	                }
695	                if (lastName.equals(Households.normalizeName(existing.getLastName()))
696	                        && postcode.equals(normalizePostcode(existing.getPostcode()))
697	                        && !equalsSafely(telephone, existing.getTelephone())
698	                        && existing.getId() != null
699	                        && (match == null || existing.getId() < match)) {
700	                    match = existing.getId();
701	                }
702	            }
703	        }
704	        owner.setPossibleDuplicate(match != null);
705	        owner.setPossibleDuplicateOf(match);
706	    }
707	
708	    /** Trim the postcode, treating a null or blank value as absent (no possible-duplicate match). */
709	    private static String normalizePostcode(String value) {
710	        if (value == null) {
711	            return null;
712	        }
713	        String trimmed = value.trim();
714	        return trimmed.isEmpty() ? null : trimmed;
715	    }
716	
717	    private static boolean equalsSafely(String a, String b) {
718	        return a == null ? b == null : a.equals(b);
719	    }
720	}
